import math
import pathlib
import re
import subprocess
import tempfile
import types
import unittest


SNAKEFILES = pathlib.Path(__file__).resolve().parents[2] / "Snakefiles"
SOURCE_ROOT = SNAKEFILES.parent
WORKFLOW_FILES = (
    "6-layoutContigs.sm",
    "7-buildPackage.sm",
    "7-generateConsensus.sm",
    "7-combineConsensus.sm",
    "7-uncompressGraph.sm",
    "8-phasing.sm",
    "8-parentalMarkers.sm",
    "8-dual.sm",
    "9-scaffolding.sm",
    "10-consensus.sm",
)
RULE_START = re.compile(r"^(?:rule|checkpoint)\s+([A-Za-z0-9_]+):", re.MULTILINE)


def rule_blocks(path):
    """Yield each top-level Snakemake rule/checkpoint and its source block."""
    source = path.read_text()
    starts = list(RULE_START.finditer(source))
    for index, match in enumerate(starts):
        end = starts[index + 1].start() if index + 1 < len(starts) else len(source)
        yield match.group(1), source[match.start():end]


class SnakemakeConventionTests(unittest.TestCase):
    def test_ci_installs_dependencies_outside_conda_base(self):
        """Mamba must not replace itself while changing the base Python ABI."""
        workflow = (SOURCE_ROOT.parent / ".github/workflows/makefile.yml").read_text()
        self.assertIn("shell: bash -el {0}", workflow)
        self.assertIn("activate-environment: verkko-ci", workflow)
        self.assertIn("conda-remove-defaults: 'true'", workflow)
        self.assertIn("channel-priority: strict", workflow)
        self.assertNotIn("auto-update-conda: true", workflow)
        self.assertNotIn("mamba install -c", workflow)
        self.assertNotIn("'python=3.11' 'pulp", workflow)

    def test_mbg_includes_read_end_kmers(self):
        """Retain read ends when MBG constructs the initial graph."""
        workflow = (SNAKEFILES / "1-buildGraph.sm").read_text()
        self.assertIn("--include-end-kmers", workflow)

    def test_mbg_automatic_memory_estimate_has_headroom(self):
        """Scale the automatic MBG estimate without changing explicit overrides."""
        functions = (SNAKEFILES / "functions.sm").read_text()
        start = functions.index("def getMBGMemoryRequest(attempt):")
        end = functions.index("def getBuildPackagesInputONT", start)
        estimator = functions[start:end]
        self.assertIn("if mem < 2.0:", estimator)
        self.assertIn("mem = mem * 1.5", estimator)

        namespace = {
            "math": math,
            "config": {"mbg_mem_gb": "0"},
            "getFileBP": lambda _: 2 * 1024**3,
            "rules": types.SimpleNamespace(
                correctHiFi=types.SimpleNamespace(
                    output=types.SimpleNamespace(fasta="corrected.fasta")
                )
            ),
        }
        exec(estimator, namespace)
        self.assertEqual(5, namespace["getMBGMemoryRequest"](1))

        namespace["config"]["mbg_mem_gb"] = "64"
        self.assertEqual(64, namespace["getMBGMemoryRequest"](1))

    def test_paths_mode_reads_quoted_inputs_portably(self):
        """The --paths config reader must work with BSD sed on macOS."""
        launcher = (SOURCE_ROOT / "verkko.sh").read_text()
        function_start = launcher.index("checkOptionEnabled() {")
        function_end = launcher.index("#  Use 'cd' and 'pwd'", function_start)
        config_helpers = launcher[function_start:function_end]

        with tempfile.TemporaryDirectory() as temp_dir:
            config = pathlib.Path(temp_dir) / "verkko.yml"
            config.write_text(
                "HIFI_READS:\n"
                " - '/tmp/read one.fastq.gz'\n"
                ' - "/tmp/read2.fastq.gz"\n'
                "withONT: 'False'\n"
            )
            result = subprocess.run(
                [
                    "bash",
                    "-c",
                    config_helpers + '\nfindInputFiles "$1" "" "HIFI_READS"',
                    "paths-config-test",
                    str(config),
                ],
                check=True,
                capture_output=True,
                text=True,
            )

        self.assertEqual(
            ["/tmp/read one.fastq.gz", "/tmp/read2.fastq.gz"],
            result.stdout.splitlines(),
        )

        # Consensus-only mode must override any ordinary assembly/phasing
        # target selection and must continue to request the legacy cnspath
        # publisher used for user-supplied GAF paths.
        phase_target = launcher.index('target="finalPhasedAssembly"')
        paths_condition = launcher.index('if [ "x$cnspaths" != "x" ]', phase_target)
        paths_target = launcher.index('target="cnspath"', paths_condition)
        self.assertLess(phase_target, paths_condition)
        self.assertLess(paths_condition, paths_target)
        for label_directory in ("8-phasing", "6-rukki", "8-hicPipeline"):
            with self.subTest(label_directory=label_directory):
                self.assertIn(f'${{cnsassembly}}/{label_directory}/label1', launcher)

    def test_feature_rules_have_cluster_resources(self):
        """Every affected job must expose the fields used by grid profiles."""
        required = ("threads:", "resources:", "job_id", "n_cpus", "mem_gb", "time_h")
        for filename in WORKFLOW_FILES:
            for rule_name, block in rule_blocks(SNAKEFILES / filename):
                for field in required:
                    with self.subTest(file=filename, rule=rule_name, field=field):
                        self.assertIn(field, block)

    def test_feature_rules_leave_reproducible_shell_scripts(self):
        """Commands must be saved, made executable and run from the workflow."""
        for filename in WORKFLOW_FILES:
            for rule_name, block in rule_blocks(SNAKEFILES / filename):
                with self.subTest(file=filename, rule=rule_name):
                    script = re.search(r"cat > \./([^\s]+\.sh) <<(?:EOF|'EOF')", block)
                    self.assertIsNotNone(script)
                    script_path = script.group(1)
                    self.assertIn(f"chmod +x ./{script_path}", block)
                    self.assertIn(f"./{script_path}", block)

