    def test_uncompressed_graph_uses_first_consensus_and_coverage(self):
        """alignGFA must restore regular-space sequence with published coverage."""
        workflow = (SNAKEFILES / "7-uncompressGraph.sm").read_text()
        install_manifest = (SOURCE_ROOT / "main.mk").read_text()

        for fragment in (
            "-e 0.25",
            "-i assembly.homopolymer-compressed.gfa",
            "-T unitigs.fasta 0",
            "-t {threads}",
            "-o assembly.gfa",
            "inject_coverage.py --allow-absent",
            "threads:\n        8",
            "n_cpus = 8",
        ):
            with self.subTest(fragment=fragment):
                self.assertIn(fragment, workflow)
        self.assertIn("Snakefiles/7-uncompressGraph.sm", install_manifest)

        snakefile = (SOURCE_ROOT / "Snakefile").read_text()
        final_consensus = (SNAKEFILES / "10-consensus.sm").read_text()
        self.assertGreaterEqual(snakefile.count("assembly.gfa"), 2)
        self.assertIn("ugraph     = 'assembly.gfa'", final_consensus)

        launcher = (SOURCE_ROOT / "verkko.sh").read_text()
        self.assertIn('paths_source_ugraph="${cnsassembly}/assembly.gfa"', launcher)
        self.assertIn('if [ -e "${cnsassembly}/assembly.gfa" ]', launcher)
        self.assertIn("--paths changes consensus paths, not the underlying unitig graph", launcher)
        self.assertNotIn("graph_unitig_consensus", launcher)

    def test_trio_markers_use_reads_then_assembly_single_copy_filter(self):
        """Do not confuse child-read abundance with assembly copy number."""
        workflow = (SNAKEFILES / "8-parentalMarkers.sm").read_text()
        builder = (SOURCE_ROOT / "scripts" / "build_parental_markers.sh").read_text()

        marker_args = workflow[workflow.index("def marker_read_args"):workflow.index("rule buildParentalMarkers")]
        self.assertIn("for path in HIFI_READS", marker_args)
        self.assertIn("['--child', shlex.quote(path)]", marker_args)
        self.assertNotIn("unitig_fasta", marker_args)
        self.assertIsNotNone(
            re.search(r"rule buildParentalMarkers:.*?mem_gb\s*=\s*128", workflow, re.DOTALL)
        )

        count = builder.index('output "$OUT/assembly.meryl"')
        single = builder.index('equal-to 1 "$OUT/assembly.meryl"')
        filter_paternal = builder.index('paternal.$SELECTED.inherited.single-copy.meryl')
        lookup = builder.index('"$LOOKUP" -existence', filter_paternal)
        self.assertLess(count, single)
        self.assertLess(single, filter_paternal)
        self.assertLess(filter_paternal, lookup)
        self.assertIn('paternal.$SELECTED.inherited.single-copy.meryl', builder[lookup:])
        self.assertIn('maternal.$SELECTED.inherited.single-copy.meryl', builder[lookup:])
        lookup_command = builder[lookup:builder.index("-sequence", lookup)]
        self.assertLess(lookup_command.index("maternal.$SELECTED"), lookup_command.index("paternal.$SELECTED"))

    def test_phase_evidence_keeps_rukki_order_and_paternal_hap1(self):
        """Evidence stays maternal-first while final output 1 is paternal."""
        parental = (SNAKEFILES / "8-parentalMarkers.sm").read_text()
        phasing = (SNAKEFILES / "8-phasing.sm").read_text()
        colorer = (SOURCE_ROOT / "scripts" / "color_parental_markers.py").read_text()
        fusion = (SOURCE_ROOT / "scripts" / "fuse_phase_evidence.py").read_text()
        cluster = (SOURCE_ROOT / "scripts" / "cluster.py").read_text()
        shared = (SOURCE_ROOT / "scripts" / "phase_evidence.py").read_text()

        self.assertIn('PHASE_COUNT_HEADER = "node\\tmaternal\\tpaternal', shared)
        for consumer in (colorer, fusion, cluster):
            self.assertIn("PHASE_COUNT_HEADER", consumer)
        self.assertIn("--hap-names maternal,paternal", parental)
        self.assertIn("hap_names = 'maternal,paternal'", phasing)
        self.assertIn("echo paternal > ../{output.label1}", parental)
        self.assertIn("label1 = 'paternal'", phasing)

