    def test_dual_with_contacts_uses_dual_paths_then_scaffolding(self):
        """Hi-C/Pore-C must scaffold dual paths without replacing their phasing."""
        launcher = (SOURCE_ROOT / "verkko.sh").read_text()
        workflow = (SNAKEFILES / "8-phasing.sm").read_text()

        validation_start = launcher.index('if [ "x$dual_assembly" = "xTrue" ]')
        validation_end = launcher.index("\nfi", validation_start)
        dual_validation = launcher[validation_start:validation_end]
        self.assertIn("maternal$paternal", dual_validation)
        self.assertNotIn("withhic", dual_validation)
        self.assertNotIn("withporec", dual_validation)

        dual_mode = launcher.index('elif [ "x$dual_assembly" = "xTrue" ]')
        contact_mode = launcher.index('elif [ "x$withhic" = "xTrue"', dual_mode)
        self.assertLess(dual_mode, contact_mode)

        selector_start = workflow.index("def selectedPhasePaths")
        selector_end = workflow.index("def selectedPhaseColors", selector_start)
        selector = workflow[selector_start:selector_end]
        self.assertLess(selector.index("if mode == 'dual'"), selector.index("if contacts:"))
        self.assertIn("8-phasing/dual.paths.gaf", selector)

        scaffolding = (SNAKEFILES / "9-scaffolding.sm").read_text()
        self.assertIn("tsv_path = '8-phasing/rukki.paths.tsv'", scaffolding)
        self.assertIn("gaf_path = '8-phasing/rukki.paths.gaf'", scaffolding)

    def test_dual_always_targets_full_consensus(self):
        """Dual mode must publish sequence, not stop after graph path selection."""
        launcher = (SOURCE_ROOT / "verkko.sh").read_text()
        snakefile = (SOURCE_ROOT / "Snakefile").read_text()
        consensus = (SNAKEFILES / "10-consensus.sm").read_text()

        dual_mode = launcher.index('elif [ "x$dual_assembly" = "xTrue" ]')
        contact_mode = launcher.index('elif [ "x$withhic" = "xTrue"', dual_mode)
        self.assertIn('phase_enable="True"', launcher[dual_mode:contact_mode])
        self.assertIn('target="finalPhasedAssembly"', launcher)
        self.assertIn("if PHASE_ENABLED:", snakefile)
        self.assertIn("include: 'Snakefiles/10-consensus.sm'", snakefile)
        for output in (
            "assembly.fasta",
            "assembly.haplotype1.fasta",
            "assembly.haplotype2.fasta",
            "assembly.unassigned.fasta",
        ):
            with self.subTest(output=output):
                self.assertIn(output, consensus)


